    const welcomeBtn = page.getByRole("button", { name: "Close Welcome Banner" });
    if (await welcomeBtn.isVisible()) await welcomeBtn.click();
    // Verify we are logged in: account button should not say "Account" with no user
    // (basket count starts at 0 for a fresh session)
  });

  await test.step("When I click Add to Basket for Apple Juice (1000ml)", async () => {
    // Find the article containing "Apple Juice (1000ml)" and click its Add to Basket button
    const article = page.locator("article", { hasText: "Apple Juice (1000ml)" }).first();
    await article.getByRole("button", { name: "Add to Basket" }).click();
  });

  await test.step("Then a confirmation is displayed on screen", async () => {
    // AC-1: "confirms it on screen" — the app shows a message that the product was added
    // Juice Shop shows a snackbar with the product name
    await expect(page.locator("mat-snack-bar-container")).toBeVisible();
  });

  await test.step("And the basket count in the top bar goes up by one", async () => {
    // The basket count is in the shopping cart button's child span
    await expect(page.getByRole("button", { name: "Show the shopping cart" }).locator("span.mat-badge-content, .mat-badge-content")).toHaveText("1");
  });
});

